/*
	VIOC_towns_curated.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "towns_capital", parte 1: lista curada de pueblos por mapa. Parametro de lobby VIOC_TOWNS_CURATED:
	  0 = como el original (decide "TOWNS: Amount"),
	  1 = lista A (todas las islas),
	  2 = lista B (solo las islas unidas por tierra o por puente a la isla principal; por defecto).
	Se ejecuta en TODAS las maquinas desde Common\Init\Init_LocationMode.sqf, justo antes de CTI_TownModeSet. Usa el
	camino de la mision para quitar pueblos: Common\Init\Init_Location.sqf agrega a TownTemplate cada pueblo que no esta
	en VIOC_TC_KEEP, y ese pueblo queda "cti_town_inactive" (fuera de CTI_Towns). Asi todo lo que sigue (campamentos,
	defensas, marcadores, victoria, modo de inicio, IA, aerodromos, bases avanzadas) queda igual en servidor y clientes.
	Mapas sin lista en VIOC_TC_LISTS: el parametro no hace nada y "TOWNS: Amount" funciona como siempre.
	Las listas se escribieron con el analisis de islas y puentes del terreno (work/v6_build/towns_capital/REPORT.txt).
	OJO: una partida guardada recuerda los pueblos por orden; al cambiar la lista empieza una partida NUEVA.

	Tambien define aqui (porque este archivo corre antes de que el servidor elija las bases de inicio):
	  VIOC_TC_CAPITALS / VIOC_TC_fnc_findCapital: la capital del mapa (la usa VIOC_towns_capital.sqf).
	  VIOC_TC_fnc_filterStarts: con VIOC_CAPITAL_DEFENSE = 1, Server\Init\Init_Server.sqf (gancho antes de "Place both
	  sides") quita de los puntos de inicio (marcadores cti-spawn*) los que estan a menos de VIOC_TC_START_EXCLUDE m de la
	  capital, siempre que queden al menos VIOC_TC_START_MIN; si no, los deja todos y lo anota en el registro. No se aplica
	  al bando que empieza con la capital: otro parche (p. ej. mission_b_rules) lo anota en VIOC_TC_START_EXEMPT = [bando].
	  Tanoa: se quitan cti-spawn8 (1,0 km de Georgetown), cti-spawn0 (1,5 km) y cti-spawn4 (2,2 km); quedan 9.
*/

//--- [mundo en minusculas, lista A, lista B] (nombres exactos de los pueblos del mission.sqm)
VIOC_TC_LISTS = [
	["tanoa",
		["Georgetown", "Georgetown Port", "Nicolet", "La Rochelle", "La Rochelle Aerodrome", "Blue Pearl Port", "Ba",
		 "Comms Bravo", "Red Spring Surface Mine", "Tanouka", "Lumberyard North",
		 "Regina", "Railway Depot", "Diesel Power Plant", "Aeroport de Tanoa", "Lumberyard South", "Oumere", "Kotomo",
		 "Harcourt", "Lijnhaven", "Port-Boise", "Moddergat",
		 "Katkoula", "Yanukka", "Balavu", "Tuvanaka", "Tuvanaka Airbase"],
		["Georgetown", "Georgetown Port", "Nicolet", "Saint-Paul", "La Rochelle", "La Rochelle Aerodrome", "Blue Pearl Port", "Ba",
		 "Comms Bravo", "Red Spring Surface Mine", "Tanouka", "Lumberyard North",
		 "Regina", "Railway Depot", "Diesel Power Plant", "Aeroport de Tanoa", "Lumberyard South", "Oumere", "Kotomo", "Nandai",
		 "Harcourt", "Lijnhaven", "Port-Boise", "Moddergat"]
	]
];

VIOC_TC_KEEP = nil;
private _vioc_mode = missionNamespace getVariable ["VIOC_TOWNS_CURATED", 2];
if (_vioc_mode > 0) then {
	private _vioc_i = VIOC_TC_LISTS findIf {(_x select 0) == toLower worldName};
	if (_vioc_i >= 0) then {
		VIOC_TC_KEEP = +((VIOC_TC_LISTS select _vioc_i) select ([1, 2] select (_vioc_mode >= 2)));
		TownTemplate = []; //--- la plantilla de "TOWNS: Amount" no se usa: Init_Location.sqf quita los que no estan en la lista
		diag_log format ["[VIOC towns_capital] %1: lista curada %2 (%3 pueblos): %4", worldName, ["A", "B"] select (_vioc_mode >= 2), count VIOC_TC_KEEP, VIOC_TC_KEEP];
	} else {
		diag_log format ["[VIOC towns_capital] %1 no tiene lista curada: se usa TOWNS: Amount", worldName];
	};
};

//--- ---------------------------------- capital y bases de inicio ----------------------------------
VIOC_TC_CAPITALS = [["tanoa", "Georgetown"]]; // [mundo en minusculas, capital]
VIOC_TC_START_EXCLUDE = 2500;     // m: ninguna base empieza tan cerca de la capital reforzada
VIOC_TC_START_MIN = 4;            // puntos de inicio minimos que tienen que quedar (si no, no se quita ninguno)
if (isNil "VIOC_TC_START_EXEMPT") then {VIOC_TC_START_EXEMPT = []}; // bandos a los que no se aplica (los que empiezan con la capital)

//--- -> la capital (pueblo de CTI_Towns): la de VIOC_TC_CAPITALS si esta en juego; si no, el de mas maxSV base sin
//--- contar sitios militares (vioc_site_mult >= 2) y, entre iguales, el de mas edificios a 250 m. objNull sin pueblos.
VIOC_TC_fnc_findCapital = {
	if (isNil "CTI_Towns") exitWith {objNull};
	private _want = "";
	private _i = VIOC_TC_CAPITALS findIf {(_x select 0) == toLower worldName};
	if (_i >= 0) then {_want = (VIOC_TC_CAPITALS select _i) select 1};
	private _cap = objNull;
	if (_want != "") then {
		{ if ((_x getVariable ["cti_town_name", ""]) == _want) exitWith {_cap = _x} } forEach CTI_Towns;
	};
	if (isNull _cap) then {
		private _keys = [];
		{
			if ((_x getVariable ["vioc_site_mult", 1]) < 2) then {
				private _sv = _x getVariable ["vioc_site_maxSV0", _x getVariable ["cti_town_maxSV", 0]];
				private _p = getPosATL _x;
				private _nb = count (nearestTerrainObjects [[_p select 0, _p select 1, 0], ["BUILDING", "HOUSE"], 250, false, true]);
				_keys pushBack [-_sv, -_nb, _forEachIndex];
			};
		} forEach CTI_Towns;
		_keys sort true;
		if (count _keys > 0) then {_cap = CTI_Towns select ((_keys select 0) select 2)};
	};
	_cap
};

//--- [lista de posiciones de inicio, etiqueta] -> la lista sin las que estan a menos de VIOC_TC_START_EXCLUDE m de la
//--- capital (solo con VIOC_CAPITAL_DEFENSE = 1, si el bando no esta en VIOC_TC_START_EXEMPT y si quedan al menos
//--- VIOC_TC_START_MIN; si no, la lista igual).
VIOC_TC_fnc_filterStarts = {
	params ["_locs", "_tag"];
	if ((missionNamespace getVariable ["VIOC_CAPITAL_DEFENSE", 1]) <= 0) exitWith {_locs};
	private _sd = [east, west] select (_tag == "oeste");
	if (_sd in (missionNamespace getVariable ["VIOC_TC_START_EXEMPT", []])) exitWith {
		diag_log format ["[VIOC towns_capital] inicio %1: este bando empieza con la capital, no se quitan puntos cercanos", _tag];
		_locs
	};
	private _cap = call VIOC_TC_fnc_findCapital;
	if (isNull _cap) exitWith {_locs};
	private _keep = _locs select {(_x distance2D _cap) >= VIOC_TC_START_EXCLUDE};
	if (count _keep < VIOC_TC_START_MIN) exitWith {
		diag_log format ["[VIOC towns_capital] inicio %1: quedarian %2 de %3 puntos lejos de %4 (minimo %5): se dejan todos", _tag, count _keep, count _locs, _cap getVariable ["cti_town_name", "?"], VIOC_TC_START_MIN];
		_locs
	};
	diag_log format ["[VIOC towns_capital] inicio %1: se quitan %2 de %3 puntos a menos de %4 m de %5", _tag, (count _locs) - (count _keep), count _locs, VIOC_TC_START_EXCLUDE, _cap getVariable ["cti_town_name", "?"]];
	_keep
};

/*
	VIOC_towns_capital.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "towns_capital", parte 2 (solo servidor; init.sqf lo lanza con execVM). La parte 1 (lista curada de pueblos,
	parametro VIOC_TOWNS_CURATED) esta en VIOC_towns_curated.sqf.

	Parametros de lobby:
	  VIOC_CAPITAL_DEFENSE      1 = capital reforzada (por defecto), 0 = no.
	  VIOC_CAPITAL_CHECKPOINTS  0 / 4 (por defecto) / 6 controles de carretera alrededor de la capital.
	  VIOC_VICTORY_CAPITAL      0 = solo la victoria original (update_victory.fsm),
	                            1 = ademas gana el bando (Oeste/Este) que mantiene la capital Y todos los pueblos con
	                                aerodromo durante VIOC_VICTORY_HOLD minutos (por defecto),
	                            2 = ademas gana el que mantiene solo la capital.
	  VIOC_VICTORY_HOLD         2 / 5 (por defecto) / 10 minutos.

	1) Capital: VIOC_TC_CAPITALS da el pueblo por mapa (Tanoa: Georgetown). Sin dato o si ese pueblo no esta en juego:
	   el pueblo con mas maxSV base (sin contar sitios militares de military_sites) y, entre iguales, el de mas edificios
	   (VIOC_TC_fnc_findCapital, en VIOC_towns_curated.sqf). Con la capital reforzada, ademas, ninguna base empieza a menos
	   de VIOC_TC_START_EXCLUDE m de ella (gancho en Server\Init\Init_Server.sqf, ver VIOC_towns_curated.sqf).
	2) Defensa (VIOC_CAPITAL_DEFENSE): todo con los mecanismos de la mision.
	   - Guarnicion: vioc_capital_mult = VIOC_TC_GARRISON_MULT en el pueblo; los ganchos de Server_SpawnTownResistance.sqf
	     y Server_SpawnTownOccupation.sqf suben los grupos a x3 (tope de 8 grupos de la mision; despues perf_cleanup
	     los recorta si se pasa el presupuesto de IA).
	   - Estaticas: 2 AA + 2 AT + 2 MG mas, a 70-260 m del centro. Son ayudantes cti_defense_kind agregados a
	     cti_town_defenses (como airfields y military_sites_statics): la mision crea la estatica de la faccion duenia,
	     la tripula cuando el pueblo se activa (Oeste/Este: solo con la mejora de pueblos, como todas las de la mision),
	     la quita al desactivarse y la cambia al capturar; fortifications le pone nido.
	   - Morteros: un foso de la mision (cti_town_mortars: 3 tubos, Server_TownMortars.sqf) solo si los morteros de
	     pueblo de los 3 bandos usan el cargador que pide la mision (VIOC_TC_MORTAR_MAG); si no, no se pone.
	3) Controles de carretera (VIOC_CAPITAL_CHECKPOINTS): en los caminos que entran a la capital, a 280-450 m del centro
	   (dentro del radio de activacion del pueblo, 550 m), uno por camino (al menos 40 grados y 200 m entre si; primero
	   las carreteras principales). Cada uno: barreras en las banquinas (el carril queda libre para los convoyes de la IA),
	   vallas de borde, cartel y bandera, con el estilo del duenio (guerrilla: sacos, neumaticos y bidones; Oeste:
	   barreras H; Este: bloques de hormigon). Ametralladora (y antitanque en uno de cada dos) con el mecanismo de defensas
	   de la mision, mirando hacia afuera (si el duenio es Oeste/Este, la mision solo las tripula con la mejora de pueblos). Al cambiar de duenio la capital: se quitan los objetos al momento y los del
	   nuevo duenio aparecen a los VIOC_TC_REBUILD_DELAY s (nunca con jugadores o vehiculos a 25 m: reintento cada 60 s).
	   Las estaticas las cambia la mision al capturar, como las demas del pueblo.
	4) Victoria (VIOC_VICTORY_CAPITAL): pueblos con aerodromo = para cada aeropuerto de CfgWorlds >> worldName (principal
	   y SecondaryAirports), el pueblo en juego mas cercano a menos de VIOC_TC_AF_RANGE de sus puntos ILS y de rodaje (la
	   misma regla que VIOC_airfields.sqf; los pueblos quitados por la lista curada no cuentan). Sin aeropuertos: solo la
	   capital. Avisos a todos al empezar la cuenta, cada minuto y si se corta. Solo cuenta si ese bando gano alguno de
	   esos pueblos durante esta partida (nunca por empezar con ellos). Al cumplirse, VIOC_TC_WINNER = bando y el gancho
	   de Server\FSM\update_victory.fsm termina la partida por su camino original (CTI_GameOver, borrado del guardado,
	   Client_OnMissionEnding con el ganador).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_TC_fnc_info); call VIOC_TC_fnc_markers;
	VIOC_TC_HOLD_TEST = 30; [west] call VIOC_TC_fnc_testGive;  (prueba de victoria: TERMINA la partida)
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_TC_RUNNING") exitWith {};
VIOC_TC_RUNNING = true;

//--- Ajustes
VIOC_TC_GARRISON_MULT = 3;        // grupos de la guarnicion de la capital (x3, tope de 8 grupos de la mision)
VIOC_TC_RING_KINDS = [["VIOC_AA", "AA"], ["VIOC_AA", "AA"], ["VIOC_AT", "AT"], ["VIOC_AT", "AT"], ["MG"], ["MG"]];
VIOC_TC_RING_RADII = [120, 90, 160, 200, 240, 75];
VIOC_TC_RING_RMAX = 260;          // m: estaticas extra a esta distancia como maximo del centro
VIOC_TC_MORTAR = true;            // foso de morteros de la mision (si el cargador coincide)
VIOC_TC_MORTAR_MAG = "8Rnd_82mm_Mo_shells"; // el que usa CTI_SE_FNC_MortarRequestFireMission
VIOC_TC_CP_RMIN = 280;            // m: controles de carretera entre RMIN y RMAX del centro
VIOC_TC_CP_RMAX = 450;
VIOC_TC_CP_RIDEAL = 360;
VIOC_TC_CP_MINANG = 40;           // grados minimos entre controles (vistos desde el centro)
VIOC_TC_CP_MINDIST = 200;         // m minimos entre controles
VIOC_TC_CP_BLOCK = 25;            // m sin jugadores ni vehiculos para levantar un control
VIOC_TC_REBUILD_DELAY = 180;      // s tras el cambio de duenio antes de levantar los controles del nuevo duenio
VIOC_TC_RETRY = 60;               // s entre reintentos si hay jugadores o vehiculos encima
VIOC_TC_AF_RANGE = 1500;          // m: pueblo duenio de un aerodromo (la misma regla que VIOC_airfields.sqf)
VIOC_TC_PERIOD = 10;              // s por pasada del bucle
//--- Disposicion de cada control (ejes locales: x = a la derecha del camino, y = hacia afuera de la ciudad):
//--- [papel, lado (+1 derecha, -1 izquierda), separacion del borde del camino, y, giro, en banquina]. "En banquina": el
//--- objeto empieza a esa distancia del borde y se extiende hacia afuera, perpendicular al camino (nunca sobre el carril).
VIOC_TC_CP_LAYOUT = [
	["wall", 1, 1, 0, 0, true], ["wall", -1, 1, 0, 0, true], ["wall", 1, 1, 10, 0, true], ["wall", -1, 1, 10, 0, true],
	["edge", 1, 0.4, 5, 0, true], ["edge", -1, 0.4, 5, 0, true],
	["sign", 1, 2, 17, 180, false], ["flag", -1, 3, -3, 0, false],
	["extra", 1, 2.5, -1, 0, false], ["extra", -1, 2.5, 6, 0, false]
];
VIOC_TC_TERRAIN = ["BUILDING", "HOUSE", "WALL", "FENCE", "ROCK", "ROCKS", "TREE"];

VIOC_TC_CAPITAL = objNull;
VIOC_TC_RING = [];
VIOC_TC_PIT = objNull;
VIOC_TC_CP = [];
VIOC_TC_AF_TOWNS = [];
VIOC_TC_HOLD = [];
VIOC_TC_GAINED = [];
VIOC_TC_INFO = [0, 0, 0]; // [controles levantados, objetos creados, cambios de duenio de la capital vistos por los controles]

//--- ---------------------------------- utilidades ----------------------------------
VIOC_TC_fnc_p0 = {
	private _p = if (_this isEqualType objNull) then {getPosATL _this} else {_this};
	[_p select 0, _p select 1, 0]
};

VIOC_TC_fnc_angDiff = {
	params ["_a", "_b"];
	abs (((((_a - _b) % 360) + 540) % 360) - 180)
};

//--- [origen, rumbo, x, y] -> punto: x a la derecha del rumbo, y hacia adelante.
VIOC_TC_fnc_lw = {
	params ["_p", "_dir", "_x0", "_y0"];
	[(_p select 0) + (_x0 * (cos _dir)) + (_y0 * (sin _dir)), (_p select 1) - (_x0 * (sin _dir)) + (_y0 * (cos _dir)), 0]
};

VIOC_TC_fnc_roofFree = {
	params ["_p"];
	(lineIntersectsSurfaces [(AGLToASL _p) vectorAdd [0, 0, 0.5], (AGLToASL _p) vectorAdd [0, 0, 40], objNull, objNull, false, 1, "GEOM", "NONE"]) isEqualTo []
};

//--- [lista de clases] -> la primera que existe ("" si ninguna).
VIOC_TC_fnc_pick = {
	(_this select {isClass (configFile >> "CfgVehicles" >> _x)}) param [0, ""]
};

VIOC_TC_fnc_sideName = {
	params ["_sid"];
	private _n = "";
	if (_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID}) then {
		{
			if ((missionNamespace getVariable [_x select 0, -9]) isEqualTo _sid) exitWith {_n = _x select 1};
		} forEach [["CTI_US_SIDE", "EE.UU."], ["CTI_SOV_SIDE", "Rusia"], ["CTI_UKRAIN_SIDE", "Ucrania"], ["CTI_BW_SIDE", "Alemania"],
			["CTI_CDF_SIDE", "Chernarus"], ["CTI_NVA_SIDE", "Vietnam del Norte"], ["CTI_CHDKZ_SIDE", "ChDKZ"]];
		if (_n == "") then {_n = ["Oeste", "Este"] select (_sid == CTI_EAST_ID)};
	} else {
		_n = "la guerrilla";
	};
	_n
};

VIOC_TC_fnc_say = {
	params ["_txt", ["_hint", false]];
	_txt remoteExec ["systemChat", 0];
	if (_hint) then {_txt remoteExec ["hint", 0]};
	diag_log format ["[VIOC towns_capital] %1", _txt];
};

//--- [sideID] -> la mision crea estaticas de pueblo para ese duenio (como Server_ManageTownDefenses.sqf)
VIOC_TC_fnc_spawnOk = {
	params ["_sid"];
	if (_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID}) exitWith {(missionNamespace getVariable ["CTI_TOWNS_OCCUPATION", 0]) > 0};
	if (_sid == CTI_RESISTANCE_ID) exitWith {(missionNamespace getVariable ["CTI_TOWNS_RESISTANCE", 0]) > 0};
	false
};

//--- Listas VIOC_AA / VIOC_AT de las estaticas de pueblo (la misma regla que VIOC_military_sites_statics.sqf; solo si
//--- ese parche no las armo ya): Oeste/Este usan sus AA/AT de pueblo; la guerrilla, CUP de AAF o las de vanilla.
VIOC_TC_fnc_initKinds = {
	if (!isNil "VIOC_SITES_STATICS_INIT") exitWith {};
	VIOC_SITES_STATICS_INIT = true;
	{
		private _sideStr = _x select 0;
		private _isGuer = _x select 1;
		{
			private _kind = _x select 0;
			private _list = +(missionNamespace getVariable [format ["CTI_%1_Defenses_%2", _sideStr, _x select 1], []]);
			if (count _list == 0 && _isGuer) then {
				_list = (_x select 2) select {isClass (configFile >> "CfgVehicles" >> _x)};
				if (count _list == 0) then {_list = (_x select 3) select {isClass (configFile >> "CfgVehicles" >> _x)}};
			};
			if (count _list > 0) then {missionNamespace setVariable [format ["CTI_%1_Defenses_%2", _sideStr, _kind], _list]};
		} forEach [
			["VIOC_AA", "AA", ["CUP_I_ZU23_AAF", "CUP_I_Igla_AA_pod_AAF"], ["I_static_AA_F"]],
			["VIOC_AT", "AT", ["CUP_I_SPG9_AAF", "CUP_I_Metis_AAF"], ["I_static_AT_F"]]
		];
	} forEach [["WEST", false], ["EAST", false], ["GUER", true]];
};

//--- [lugar, otros lugares] -> sirve para una estatica: tierra, nadie encima, fuera de calles, plano, sin techo ni objetos del mapa.
VIOC_TC_fnc_staticOk = {
	params ["_q", "_others"];
	!(surfaceIsWater _q)
	&& {((_q nearEntities [["Man", "LandVehicle", "Air", "Ship"], 6]) select {alive _x}) isEqualTo []}
	&& {([[0, 0], [4, 0], [-4, 0], [0, 4], [0, -4]] findIf {isOnRoad [(_q select 0) + (_x select 0), (_q select 1) + (_x select 1), 0]}) < 0}
	&& {(_others findIf {(_x distance2D _q) < 22}) < 0}
	&& {count (_q isFlatEmpty [-1, -1, 0.35, 3, 0, false, objNull]) > 0}
	&& {[_q] call VIOC_TC_fnc_roofFree}
	&& {(nearestTerrainObjects [_q, VIOC_TC_TERRAIN, 3, false, true]) isEqualTo []}
};

//--- [pueblo, lugar, direccion, tipos, etiqueta] -> ayudante cti_defense_kind agregado a cti_town_defenses (y su estatica
//--- si la mision la crearia para el duenio actual, como hace VIOC_airfields.sqf).
VIOC_TC_fnc_addDefense = {
	params ["_town", "_p", "_dir", "_kinds", "_tag"];
	private _h = "Land_ClutterCutter_small_F" createVehicleLocal _p;
	_h setPos _p;
	_h setDir _dir;
	_h setVariable ["cti_defense_kind", +_kinds];
	_h setVariable ["VIOC_KEEP", true];
	_h setVariable ["vioc_tc_def", _tag];
	private _defs = _town getVariable ["cti_town_defenses", []];
	_defs pushBack _h;
	_town setVariable ["cti_town_defenses", _defs];
	private _sid = _town getVariable ["cti_town_sideID", -1];
	if ([_sid] call VIOC_TC_fnc_spawnOk) then {[_h, (_sid) call CTI_CO_FNC_GetSideFromID] call CTI_SE_FNC_SpawnTownDefense};
	_h
};

//--- ---------------------------------- 1) capital ----------------------------------
//--- VIOC_TC_CAPITALS y VIOC_TC_fnc_findCapital estan en VIOC_towns_curated.sqf (tambien los usa la eleccion de bases de inicio).

//--- ---------------------------------- 2) defensa ----------------------------------
//--- [capital] -> [[lugar, direccion, tipos], ...]: un sector de 60 grados por estatica, el primer lugar que sirve.
VIOC_TC_fnc_ringSpots = {
	params ["_town"];
	private _c = _town call VIOC_TC_fnc_p0;
	private _others = ((_town getVariable ["cti_town_defenses", []]) select {!isNull _x}) apply {_x call VIOC_TC_fnc_p0};
	{ _others pushBack (_x call VIOC_TC_fnc_p0) } forEach (_town getVariable ["cti_town_camps", []]);
	_others pushBack _c;
	private _chosen = [];
	private _a0 = random 360;
	private _n = count VIOC_TC_RING_KINDS;
	{
		private _kinds = _x;
		private _base = _a0 + (_forEachIndex * (360 / _n));
		private _done = false;
		{
			private _r = _x;
			{
				private _q = (_c getPos [_r, _base + _x]) findEmptyPosition [0, 15, "I_static_AA_F"];
				if (count _q > 1) then {
					_q = [_q select 0, _q select 1, 0];
					if ((_q distance2D _c) <= VIOC_TC_RING_RMAX && {(_chosen findIf {((_x select 0) distance2D _q) < 35}) < 0} && {[_q, _others] call VIOC_TC_fnc_staticOk}) then {
						_chosen pushBack [_q, _c getDir _q, _kinds];
						_done = true;
					};
				};
				if (_done) exitWith {};
			} forEach [0, 20, -20, 40, -40];
			if (_done) exitWith {};
		} forEach VIOC_TC_RING_RADII;
	} forEach VIOC_TC_RING_KINDS;
	_chosen
};

//--- true si los morteros de pueblo de los 3 bandos (los que existan) usan el cargador de la mision.
VIOC_TC_fnc_mortarOk = {
	private _ok = true;
	private _any = false;
	{
		private _l = (missionNamespace getVariable [format ["CTI_%1_Defenses_Mortar", _x], []]) select {_x isEqualType ""};
		{
			_any = true;
			private _cfg = configFile >> "CfgVehicles" >> _x;
			private _mags = [];
			{ _mags append (getArray (_x >> "magazines")) } forEach ("true" configClasses (_cfg >> "Turrets"));
			if !(isClass _cfg && {VIOC_TC_MORTAR_MAG in _mags}) exitWith {_ok = false};
		} forEach _l;
	} forEach [west, east, resistance];
	_ok && _any
};

VIOC_TC_fnc_mortarPit = {
	params ["_town"];
	if (!isNil {_town getVariable "cti_town_mortars"}) exitWith {diag_log "[VIOC towns_capital] la capital ya tiene morteros de la mision"};
	if !(call VIOC_TC_fnc_mortarOk) exitWith {diag_log format ["[VIOC towns_capital] sin foso de morteros: algun mortero de pueblo no usa %1 (la mision no lo haria disparar)", VIOC_TC_MORTAR_MAG]};
	private _c = _town call VIOC_TC_fnc_p0;
	private _others = ((_town getVariable ["cti_town_defenses", []]) select {!isNull _x}) apply {_x call VIOC_TC_fnc_p0};
	private _spot = [];
	private _a0 = random 360;
	{
		private _r = _x;
		for "_i" from 0 to 11 do {
			private _q = _c getPos [_r, _a0 + (_i * 30)];
			_q = [_q select 0, _q select 1, 0];
			if (!(surfaceIsWater _q)
				&& {count (_q nearRoads 14) == 0}
				&& {(_others findIf {(_x distance2D _q) < 30}) < 0}
				&& {count (_q isFlatEmpty [8, -1, 0.25, 8, 0, false, objNull]) > 0}
				&& {[_q] call VIOC_TC_fnc_roofFree}
				&& {(nearestTerrainObjects [_q, VIOC_TC_TERRAIN, 10, false, true]) isEqualTo []}) exitWith {_spot = _q};
		};
		if (count _spot > 0) exitWith {};
	} forEach [140, 180, 110, 220];
	if (count _spot == 0) exitWith {diag_log "[VIOC towns_capital] sin lugar plano y libre para el foso de morteros"};
	private _h = "Land_ClutterCutter_small_F" createVehicleLocal _spot;
	_h setPos _spot;
	_h setDir (_c getDir _spot);
	_h setVariable ["VIOC_KEEP", true];
	_town setVariable ["cti_town_mortars", [_h]];
	VIOC_TC_PIT = _h;
	private _sid = _town getVariable ["cti_town_sideID", -1];
	if ([_sid] call VIOC_TC_fnc_spawnOk) then {[_town, (_sid) call CTI_CO_FNC_GetSideFromID] call CTI_SE_FNC_ManageTownMortars};
	diag_log format ["[VIOC towns_capital] foso de morteros en %1", _spot];
};

//--- ---------------------------------- 3) controles ----------------------------------
//--- [candidato [camino, lugar, rumbo, tipo, getRoadInfo], centro, otros lugares] -> control (HashMap) o [] si no hay
//--- lugar para la ametralladora.
VIOC_TC_fnc_cpLayout = {
	params ["_cd", "_c", "_others"];
	_cd params ["_road", "_p", "_brg", "_type", "_ri"];
	private _b = _ri param [6, []];
	private _e = _ri param [7, []];
	private _dir = if (count _b > 1 && {count _e > 1} && {(_b distance2D _e) > 0.5}) then {_b getDir _e} else {getDir _road};
	if (([_dir, _brg] call VIOC_TC_fnc_angDiff) > 90) then {_dir = (_dir + 180) % 360};
	private _w = _ri param [1, 0];
	if !(_w isEqualType 0) then {_w = 0};
	if (_w < 4) then {_w = [5, 7, 9] select ((["TRACK", "ROAD", "MAIN ROAD"] find _type) max 0)};
	private _h = _w / 2;
	private _mg = [];
	{
		private _q = [_p, _dir, _x select 0, _x select 1] call VIOC_TC_fnc_lw;
		if ([_q, _others] call VIOC_TC_fnc_staticOk) exitWith {_mg = _q};
	} forEach [[_h + 6, -4], [-(_h + 6), -4], [_h + 8, -8], [-(_h + 8), -8], [_h + 6, 3], [-(_h + 6), 3]];
	if (count _mg == 0) exitWith {[]};
	private _at = [];
	{
		private _q = [_p, _dir, _x select 0, _x select 1] call VIOC_TC_fnc_lw;
		if ((_q distance2D _mg) > 7 && {[_q, _others] call VIOC_TC_fnc_staticOk}) exitWith {_at = _q};
	} forEach [[-(_h + 7), -7], [_h + 7, -10], [-(_h + 9), -12], [_h + 9, -14]];
	createHashMapFromArray [["pos", _p], ["dir", _dir], ["brg", _brg], ["w", _w], ["type", _type], ["mg", _mg], ["at", _at],
		["props", []], ["defs", []], ["sid", -9], ["due", 0], ["first", true]]
};

//--- [capital, cuantos] -> controles: tramos de camino (no sendero, no puente) a RMIN-RMAX del centro, primero las
//--- carreteras principales y lo mas cerca de RIDEAL; uno por entrada (MINANG grados y MINDIST m entre si).
VIOC_TC_fnc_cpSpots = {
	params ["_town", "_n"];
	private _c = _town call VIOC_TC_fnc_p0;
	private _others = ((_town getVariable ["cti_town_defenses", []]) select {!isNull _x}) apply {_x call VIOC_TC_fnc_p0};
	{ _others pushBack (_x call VIOC_TC_fnc_p0) } forEach (_town getVariable ["cti_town_camps", []]);
	private _cands = [];
	private _keys = [];
	{
		private _ri = getRoadInfo _x;
		private _type = _ri param [0, ""];
		private _p = _x call VIOC_TC_fnc_p0;
		private _d = _p distance2D _c;
		if (_d >= VIOC_TC_CP_RMIN && {_d <= VIOC_TC_CP_RMAX} && {_type in ["MAIN ROAD", "ROAD", "TRACK"]} && {!(_ri param [2, false])} && {!(_ri param [8, false])} && {!(surfaceIsWater _p)}) then {
			private _wt = ["TRACK", "ROAD", "MAIN ROAD"] find _type;
			_keys pushBack [((-(_wt + 1)) * 1000) + (abs (_d - VIOC_TC_CP_RIDEAL)), count _cands];
			_cands pushBack [_x, _p, _c getDir _p, _type, _ri];
		};
	} forEach (_c nearRoads (VIOC_TC_CP_RMAX + 10));
	_keys sort true;
	private _pick = [];
	{
		private _cd = _cands select (_x select 1);
		if ((_pick findIf {(([_cd select 2, _x get "brg"] call VIOC_TC_fnc_angDiff) < VIOC_TC_CP_MINANG) || {((_cd select 1) distance2D (_x get "pos")) < VIOC_TC_CP_MINDIST}}) < 0) then {
			private _cp = [_cd, _c, _others + ((_pick apply {_x get "mg"}) + ((_pick apply {_x get "at"}) select {count _x > 1}))] call VIOC_TC_fnc_cpLayout;
			if !(_cp isEqualTo []) then {_pick pushBack _cp};
		};
		if (count _pick >= _n) exitWith {};
	} forEach _keys;
	diag_log format ["[VIOC towns_capital] %1 tramos de camino candidatos para controles; elegidos %2 de %3", count _cands, count _pick, _n];
	_pick
};

//--- [sideID] -> HashMap papel -> clase, segun el duenio.
VIOC_TC_fnc_style = {
	params ["_sid"];
	private _green = missionNamespace getVariable ["VIOC_FORT_GREEN", false];
	private _flag = missionNamespace getVariable ["CTI_CO_CAMP_FLAG", "FlagPole_F"];
	if !(_flag isEqualType "") then {_flag = "FlagPole_F"};
	private _m = createHashMap;
	switch (true) do {
		case (_sid == CTI_WEST_ID): {
			_m set ["wall", (if (_green) then {["Land_HBarrier_01_line_3_green_F", "Land_HBarrier_3_F"]} else {["Land_HBarrier_3_F"]}) call VIOC_TC_fnc_pick];
			_m set ["edge", ["Land_RoadBarrier_01_F", "RoadBarrier_F"] call VIOC_TC_fnc_pick];
			_m set ["sign", ["Land_Sign_WarningMilitaryArea_F"] call VIOC_TC_fnc_pick];
		};
		case (_sid == CTI_EAST_ID): {
			_m set ["wall", ["Land_CncBarrierMedium4_F", "Land_CncBarrierMedium_F", "Land_HBarrier_3_F"] call VIOC_TC_fnc_pick];
			_m set ["edge", ["Land_RoadBarrier_01_F", "RoadBarrier_F"] call VIOC_TC_fnc_pick];
			_m set ["sign", ["Land_Sign_WarningMilitaryArea_F"] call VIOC_TC_fnc_pick];
		};
		default {
			_m set ["wall", (if (_green) then {["Land_SandbagBarricade_01_half_F", "Land_BagFence_01_long_green_F", "Land_BagFence_Long_F"]} else {["Land_SandbagBarricade_01_half_F", "Land_BagFence_Long_F"]}) call VIOC_TC_fnc_pick];
			_m set ["edge", ["Land_Tyres_F"] call VIOC_TC_fnc_pick];
			_m set ["sign", ["Land_Sign_WarningMilAreaSmall_F", "Land_Sign_WarningMilitaryArea_F"] call VIOC_TC_fnc_pick];
			_m set ["extra", ["Land_MetalBarrel_F"] call VIOC_TC_fnc_pick];
		};
	};
	_m set ["flag", [_flag, "FlagPole_F"] call VIOC_TC_fnc_pick];
	_m
};

//--- [clase, centro del control, rumbo, medio ancho, lado, separacion, y, giro, en banquina] -> objeto o objNull si el
//--- lugar no sirve (agua, calle, alguien o algo encima, objetos del mapa).
VIOC_TC_fnc_place = {
	params ["_cls", "_p", "_dir", "_h", "_sgn", "_xe", "_y0", "_rel", "_shoulder"];
	private _o = createVehicle [_cls, [0, 0, 0], [], 0, "NONE"]; //--- se crea lejos y se mueve despues de revisar el lugar
	if (isNull _o) exitWith {objNull};
	(boundingBoxReal _o) params ["_b1", "_b2"];
	private _lx = ((_b2 select 0) - (_b1 select 0)) max 0.5;
	private _ly = ((_b2 select 1) - (_b1 select 1)) max 0.5;
	private _d = _dir + _rel;
	private _len = _lx;
	if (_shoulder && {_ly > _lx}) then {_d = _d + 90; _len = _ly};
	private _x0 = if (_shoulder) then {_sgn * (_h + _xe + (_len / 2))} else {_sgn * (_h + _xe)};
	private _q = [_p, _dir, _x0, _y0] call VIOC_TC_fnc_lw;
	private _r = ((_lx max _ly) / 2) + 0.5;
	private _ok = !(surfaceIsWater _q) && {!(isOnRoad _q)}
		&& {((_q nearEntities [["Man", "LandVehicle", "Air", "Ship"], _r + 1]) select {alive _x}) isEqualTo []}
		&& {(nearestTerrainObjects [_q, VIOC_TC_TERRAIN, _r, false, true]) isEqualTo []}
		&& {((nearestObjects [_q, [], _r]) findIf {(_x != _o) && {!isNil {_x getVariable "vioc_fort"}}}) < 0}; //--- ni sobre un nido de fortifications
	if (!_ok) exitWith {deleteVehicle _o; objNull};
	_o setDir _d;
	_o setPosATL _q;
	_o setVectorUp (surfaceNormal _q);
	_o setVariable ["VIOC_KEEP", true];
	_o setVariable ["vioc_tc_prop", true];
	_o
};

//--- [control] -> quita sus objetos (las estaticas son de la mision y no se tocan).
VIOC_TC_fnc_cpClear = {
	params ["_cp"];
	{ if (!isNull _x) then {deleteVehicle _x} } forEach (_cp get "props");
	_cp set ["props", []];
	_cp set ["sid", -9];
};

//--- [control, sideID] -> true si se levanto; false si hay jugadores o vehiculos encima (se reintenta).
VIOC_TC_fnc_cpBuild = {
	params ["_cp", "_sid"];
	private _p = _cp get "pos";
	private _near = (_p nearEntities [["Man", "LandVehicle", "Air", "Ship"], VIOC_TC_CP_BLOCK]) select {alive _x && {!(_x isKindOf "StaticWeapon")}};
	if ((_near findIf {isPlayer _x || {!(_x isKindOf "Man")}}) >= 0) exitWith {false};
	private _style = [_sid] call VIOC_TC_fnc_style;
	private _dir = _cp get "dir";
	private _h = (_cp get "w") / 2;
	private _tex = missionNamespace getVariable [format ["CTI_%1FLAG", (_sid) call CTI_CO_FNC_GetSideFromID], ""];
	private _props = [];
	{
		_x params ["_role", "_sgn", "_xe", "_y0", "_rel", "_shoulder"];
		private _cls = _style getOrDefault [_role, ""];
		if (_cls != "") then {
			private _o = [_cls, _p, _dir, _h, _sgn, _xe, _y0, _rel, _shoulder] call VIOC_TC_fnc_place;
			if (!isNull _o) then {
				if (_role == "flag") then {
					if (_tex isEqualType "" && {_tex != ""}) then {_o setFlagTexture _tex};
				} else {
					_o enableSimulationGlobal false;
					if (_role == "wall") then {_o allowDamage false};
				};
				_props pushBack _o;
			};
		};
	} forEach VIOC_TC_CP_LAYOUT;
	_cp set ["props", _props];
	VIOC_TC_INFO set [0, (VIOC_TC_INFO select 0) + 1];
	VIOC_TC_INFO set [1, (VIOC_TC_INFO select 1) + (count _props)];
	true
};

//--- Cada pasada: si el duenio de la capital cambio, quita los objetos y, tras la espera, levanta los del nuevo duenio.
VIOC_TC_fnc_cpTick = {
	private _sid = VIOC_TC_CAPITAL getVariable ["cti_town_sideID", -1];
	private _built = 0;
	{
		private _cp = _x;
		if ((_cp get "sid") != _sid) then {
			if ((_cp get "due") == 0) then {
				if (!(_cp get "first") && {_forEachIndex == 0}) then {VIOC_TC_INFO set [2, (VIOC_TC_INFO select 2) + 1]};
				[_cp] call VIOC_TC_fnc_cpClear;
				_cp set ["due", time + ([VIOC_TC_REBUILD_DELAY, 0] select (_cp get "first"))];
			};
			if (time >= (_cp get "due")) then {
				if ([_cp, _sid] call VIOC_TC_fnc_cpBuild) then {
					_cp set ["sid", _sid];
					_cp set ["due", 0];
					if !(_cp get "first") then {_built = _built + 1};
					_cp set ["first", false];
				} else {
					_cp set ["due", time + VIOC_TC_RETRY];
				};
			};
		};
	} forEach VIOC_TC_CP;
	if (_built > 0) then {
		[format ["%1: %2 controles de carretera ahora son de %3.", VIOC_TC_CAPITAL getVariable ["cti_town_name", "la capital"], _built, [_sid] call VIOC_TC_fnc_sideName]] call VIOC_TC_fnc_say;
	};
};

//--- ---------------------------------- 4) victoria ----------------------------------
//--- Pueblos en juego duenios de un aerodromo: la misma regla que VIOC_airfields.sqf (VIOC_AF_fnc_buildTable).
VIOC_TC_fnc_airfieldTowns = {
	private _wcfg = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_wcfg];
	if (isClass (_wcfg >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_wcfg >> "SecondaryAirports"))};
	private _fnc_in = {(_this select 0) isEqualType 0 && {(_this select 1) isEqualType 0} && {(_this select 0) > 0} && {(_this select 1) > 0} && {(_this select 0) < worldSize} && {(_this select 1) < worldSize}};
	private _res = [];
	{
		private _c = _x;
		private _ils = getArray (_c >> "ilsPosition");
		if (count _ils > 1 && {_ils call _fnc_in}) then {
			private _pts = [[_ils select 0, _ils select 1, 0]];
			{
				private _flat = getArray (_c >> _x);
				for "_j" from 0 to ((count _flat) - 2) step 2 do {
					private _q = [_flat select _j, _flat select (_j + 1), 0];
					if (_q call _fnc_in) then {_pts pushBack _q};
				};
			} forEach ["ilsTaxiIn", "ilsTaxiOff"];
			private _town = objNull;
			private _bd = VIOC_TC_AF_RANGE;
			{
				private _tw = _x;
				{ private _d = _tw distance2D _x; if (_d < _bd) then {_bd = _d; _town = _tw} } forEach _pts;
			} forEach CTI_Towns;
			if (!isNull _town) then {_res pushBackUnique _town};
			diag_log format ["[VIOC towns_capital] aerodromo %1 -> %2", configName _c, if (isNull _town) then {"sin pueblo en juego a 1,5 km (no cuenta)"} else {_town getVariable ["cti_town_name", "?"]}];
		};
	} forEach _cfgs;
	if (!isNil "VIOC_AF_TABLE") then {
		private _af = (VIOC_AF_TABLE apply {_x getOrDefault ["town", objNull]}) select {!isNull _x};
		if !((_af - _res) isEqualTo [] && {(_res - _af) isEqualTo []}) then {diag_log format ["[VIOC towns_capital] OJO: VIOC_AF_TABLE da otros pueblos: %1", _af apply {_x getVariable ["cti_town_name", "?"]}]};
	};
	_res
};

VIOC_TC_fnc_reqTowns = {
	private _mode = missionNamespace getVariable ["VIOC_VICTORY_CAPITAL", 1];
	if (_mode <= 0 || {isNull VIOC_TC_CAPITAL}) exitWith {[]};
	[VIOC_TC_CAPITAL] + ([[], VIOC_TC_AF_TOWNS] select (_mode == 1))
};

VIOC_TC_fnc_reqText = {
	private _af = (call VIOC_TC_fnc_reqTowns) - [VIOC_TC_CAPITAL];
	private _t = format ["la capital (%1)", VIOC_TC_CAPITAL getVariable ["cti_town_name", "?"]];
	if (count _af == 1) then {_t = _t + format [" y el aerodromo (%1)", (_af select 0) getVariable ["cti_town_name", "?"]]};
	if (count _af > 1) then {_t = _t + format [" y los %1 aerodromos (%2)", count _af, (_af apply {_x getVariable ["cti_town_name", "?"]}) joinString ", "]};
	_t
};

VIOC_TC_fnc_victoryTick = {
	if (!isNil "VIOC_TC_WINNER") exitWith {};
	private _req = call VIOC_TC_fnc_reqTowns;
	if (count _req == 0) exitWith {};
	private _hold = (missionNamespace getVariable ["VIOC_VICTORY_HOLD", 5]) * 60;
	if (!isNil "VIOC_TC_HOLD_TEST") then {_hold = VIOC_TC_HOLD_TEST};
	//--- quien gano alguno de estos pueblos en esta partida
	{
		private _sid = _x getVariable ["cti_town_sideID", -1];
		private _old = _x getVariable ["vioc_tc_lastsid", _sid];
		if (_sid != _old && {_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID}}) then {VIOC_TC_GAINED pushBackUnique _sid};
		_x setVariable ["vioc_tc_lastsid", _sid];
	} forEach _req;
	private _owner = -1;
	{
		private _s = _x;
		if ((_req findIf {(_x getVariable ["cti_town_sideID", -1]) != _s}) < 0) exitWith {_owner = _s};
	} forEach [CTI_WEST_ID, CTI_EAST_ID];
	if (_owner >= 0 && {!(_owner in VIOC_TC_GAINED)}) then {_owner = -1};
	if (_owner < 0) exitWith {
		if (count VIOC_TC_HOLD > 0) then {
			private _was = VIOC_TC_HOLD select 0;
			private _lost = _req select {(_x getVariable ["cti_town_sideID", -1]) != _was};
			[format ["%1 perdio %2: se corta la cuenta para la victoria.", [_was] call VIOC_TC_fnc_sideName, (_lost apply {_x getVariable ["cti_town_name", "?"]}) joinString ", "], true] call VIOC_TC_fnc_say;
			VIOC_TC_HOLD = [];
		};
	};
	if (count VIOC_TC_HOLD == 0 || {(VIOC_TC_HOLD select 0) != _owner}) exitWith {
		VIOC_TC_HOLD = [_owner, time, ceil (_hold / 60)];
		[format ["%1 controla %2: victoria en %3 min si los mantiene.", [_owner] call VIOC_TC_fnc_sideName, call VIOC_TC_fnc_reqText, ceil (_hold / 60)], true] call VIOC_TC_fnc_say;
	};
	private _left = ((VIOC_TC_HOLD select 1) + _hold) - time;
	if (_left <= 0) exitWith {
		[format ["%1 mantuvo %2 durante %3 min: gana la partida.", [_owner] call VIOC_TC_fnc_sideName, call VIOC_TC_fnc_reqText, ceil (_hold / 60)], true] call VIOC_TC_fnc_say;
		VIOC_TC_WINNER = (_owner) call CTI_CO_FNC_GetSideFromID; //--- update_victory.fsm termina la partida en su proxima pasada (15 s)
	};
	private _m = ceil (_left / 60);
	if (_m < (VIOC_TC_HOLD select 2)) then {
		VIOC_TC_HOLD set [2, _m];
		[format ["%1 mantiene %2: victoria en %3 min.", [_owner] call VIOC_TC_fnc_sideName, call VIOC_TC_fnc_reqText, _m]] call VIOC_TC_fnc_say;
	};
};

//--- ---------------------------------- arranque y bucle ----------------------------------
VIOC_TC_fnc_setup = {
	if (isNil "VIOC_TC_fnc_findCapital") exitWith {diag_log "[VIOC towns_capital] falta VIOC_towns_curated.sqf (gancho de Init_LocationMode.sqf): nada que hacer"};
	VIOC_TC_CAPITAL = call VIOC_TC_fnc_findCapital;
	if (isNull VIOC_TC_CAPITAL) exitWith {diag_log "[VIOC towns_capital] no hay pueblos: nada que hacer"};
	private _cap = VIOC_TC_CAPITAL;
	_cap setVariable ["vioc_capital", true, true];
	if ((missionNamespace getVariable ["VIOC_CAPITAL_DEFENSE", 1]) > 0) then {
		_cap setVariable ["vioc_capital_mult", VIOC_TC_GARRISON_MULT];
		call VIOC_TC_fnc_initKinds;
		{ VIOC_TC_RING pushBack ([_cap, _x select 0, _x select 1, _x select 2, "ring"] call VIOC_TC_fnc_addDefense) } forEach ([_cap] call VIOC_TC_fnc_ringSpots);
		if (VIOC_TC_MORTAR) then {[_cap] call VIOC_TC_fnc_mortarPit};
	};
	private _n = missionNamespace getVariable ["VIOC_CAPITAL_CHECKPOINTS", 4];
	if (_n > 0) then {
		call VIOC_TC_fnc_initKinds;
		VIOC_TC_CP = [_cap, _n] call VIOC_TC_fnc_cpSpots;
		call VIOC_TC_fnc_cpTick; //--- primero los objetos del control: los nidos de fortifications se arman despues y los esquivan
		{
			private _cp = _x;
			private _defs = [[_cap, _cp get "mg", _cp get "dir", ["MG"], "cp"] call VIOC_TC_fnc_addDefense];
			if ((_forEachIndex % 2) == 0 && {count (_cp get "at") > 1}) then {
				_defs pushBack ([_cap, _cp get "at", _cp get "dir", ["VIOC_AT", "AT"], "cp"] call VIOC_TC_fnc_addDefense);
			};
			_cp set ["defs", _defs];
		} forEach VIOC_TC_CP;
	};
	if ((missionNamespace getVariable ["VIOC_VICTORY_CAPITAL", 1]) > 0) then {
		VIOC_TC_AF_TOWNS = (call VIOC_TC_fnc_airfieldTowns) - [_cap];
	};
	diag_log format ["[VIOC towns_capital] capital %1 (duenio %2): guarnicion x%3, %4 estaticas extra, morteros %5, %6 controles; victoria modo %7 con %8",
		_cap getVariable ["cti_town_name", "?"], _cap getVariable ["cti_town_sideID", -1], _cap getVariable ["vioc_capital_mult", 1],
		count VIOC_TC_RING, !isNull VIOC_TC_PIT, count VIOC_TC_CP, missionNamespace getVariable ["VIOC_VICTORY_CAPITAL", 1],
		VIOC_TC_AF_TOWNS apply {_x getVariable ["cti_town_name", "?"]}];
};

VIOC_TC_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 40; //--- despues de las defensas de la mision (Init_Location.sqf) y de las de airfields (30 s)
	call VIOC_TC_fnc_setup;
	if (isNull VIOC_TC_CAPITAL) exitWith {};
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		if (count VIOC_TC_CP > 0) then {call VIOC_TC_fnc_cpTick};
		call VIOC_TC_fnc_victoryTick;
		sleep VIOC_TC_PERIOD;
	};
};

