VIOC_TC_fnc_info = {
	private _nl = toString [10];
	if (isNull VIOC_TC_CAPITAL) exitWith {"VIOC towns_capital: todavia sin capital (arranca 40 s despues de los pueblos)"};
	private _cap = VIOC_TC_CAPITAL;
	private _t = format ["Capital: %1 (duenio %2, activo %3)", _cap getVariable ["cti_town_name", "?"], [_cap getVariable ["cti_town_sideID", -1]] call VIOC_TC_fnc_sideName,
		(_cap getVariable ["cti_town_resistance_active", false]) || {_cap getVariable ["cti_town_occupation_active", false]}];
	_t = _t + _nl + format ["Guarnicion x%1; defensas del pueblo %2 (extra %3); morteros %4", _cap getVariable ["vioc_capital_mult", 1],
		count (_cap getVariable ["cti_town_defenses", []]), count VIOC_TC_RING, if (isNull VIOC_TC_PIT) then {"no"} else {str count ((_cap getVariable ["cti_mortars_spawned", [[], []]]) select 0)}];
	{
		_t = _t + _nl + format ["Control %1: %2 a %3 m, rumbo %4, %5, objetos %6, de %7%8", _forEachIndex + 1, _x get "type", round ((_x get "pos") distance2D _cap),
			round (_x get "brg"), (_x get "defs") apply {typeOf (_x getVariable ["CTI_defense", objNull])}, count (_x get "props"),
			if ((_x get "sid") == -9) then {"nadie"} else {[_x get "sid"] call VIOC_TC_fnc_sideName},
			if ((_x get "due") > 0) then {format [" (se levanta en %1 s)", round ((_x get "due") - time)]} else {""}];
	} forEach VIOC_TC_CP;
	_t = _t + _nl + format ["Victoria modo %1, %2 min: %3", missionNamespace getVariable ["VIOC_VICTORY_CAPITAL", 1], missionNamespace getVariable ["VIOC_VICTORY_HOLD", 5],
		(call VIOC_TC_fnc_reqTowns) apply {[_x getVariable ["cti_town_name", "?"], [_x getVariable ["cti_town_sideID", -1]] call VIOC_TC_fnc_sideName]}];
	if (count VIOC_TC_HOLD > 0) then {_t = _t + _nl + format ["Cuenta: %1 desde hace %2 s", [VIOC_TC_HOLD select 0] call VIOC_TC_fnc_sideName, round (time - (VIOC_TC_HOLD select 1))]};
	_t + _nl + format ["Ganaron alguno en esta partida: %1; INFO %2", VIOC_TC_GAINED apply {[_x] call VIOC_TC_fnc_sideName}, VIOC_TC_INFO]
};

//--- Marcadores locales (solo en la maquina que lo ejecuta) de la capital, sus estaticas extra y los controles.
VIOC_TC_fnc_markers = {
	if (isNull VIOC_TC_CAPITAL) exitWith {"sin capital"};
	private _n = 0;
	{
		private _m = createMarkerLocal [format ["vioc_tc_ring_%1", _forEachIndex], getPosATL _x];
		_m setMarkerTypeLocal "mil_triangle";
		_m setMarkerColorLocal "ColorOrange";
		_m setMarkerTextLocal ((_x getVariable ["cti_defense_kind", ["?"]]) param [0, "?"]);
		_n = _n + 1;
	} forEach VIOC_TC_RING;
	{
		private _m = createMarkerLocal [format ["vioc_tc_cp_%1", _forEachIndex], _x get "pos"];
		_m setMarkerTypeLocal "mil_warning";
		_m setMarkerColorLocal "ColorRed";
		_m setMarkerTextLocal format ["Control %1", _forEachIndex + 1];
		_n = _n + 1;
	} forEach VIOC_TC_CP;
	if (!isNull VIOC_TC_PIT) then {
		private _m = createMarkerLocal ["vioc_tc_pit", getPosATL VIOC_TC_PIT];
		_m setMarkerTypeLocal "mil_dot";
		_m setMarkerColorLocal "ColorOrange";
		_m setMarkerTextLocal "Morteros";
		_n = _n + 1;
	};
	format ["%1 marcadores", _n]
};

